export function scopeName(scope,lang){if(scope==='World'||scope==='WORLD'||scope==='global')return dictionary(lang).scopes.en===dictionary(lang).scopes[lang]?dictionary(lang).scopes[lang]:({zh:'全球',es:'MUNDO',fr:'MONDE',ja:'世界',ko:'전 세계',ar:'العالم'})[lang]||'WORLD';if(scope==='Taiwan'||scope==='TW')return lang==='zh'?'臺灣':countryName('TW',lang);return /^[A-Z]{2}$/.test(scope||'')?countryName(scope,lang):scope;}
export class Catalogue{
 async load(){
  const response=await fetch('./assets/global-facts.json?v=5.6.3');if(!response.ok)throw Error('Global data unavailable');
  const payload=await response.json();this.global=payload.cards;this.retrievedAt=payload.retrievedAt;this.rules=payload.interactionRules;
 }
 format(c,lang){
  const w=words[lang],iso={'Japan':'JP','Spain':'ES','United States':'US','Republic of Korea':'KR'}[c.scope],unit=typeof c.unit==='object'?c.unit[lang]:c.unit;
  let value=c.value;
  if(typeof value!=='string'){
   const prefix=c.estimated?'≈ ':'';
   value=prefix+(c.format==='percent'?number(value,lang,2)+'%':c.format==='hours'?number(value,lang,2)+' '+copy[lang].hour:c.format==='ratio'?number(value,lang,2)+'×':c.format==='decimal'?number(value,lang,2)+(unit?' '+unit:''):compact(value,lang));
  }
  const yearText=c.year==='WHO guidance'?({en:'WHO GUIDANCE',zh:'WHO指引',es:'GUÍA OMS',fr:'DIRECTIVES OMS',ja:'WHO指針',ko:'WHO지침',ar:'إرشادات منظمة الصحة العالمية'})[lang]:String(c.year).replace(/\d/g,d=>number(Number(d),lang,0));
  return {...c,value,yearText,label:c.labels?.[lang]||w[c.labelKey]||extraLabels[lang]?.[c.labelKey]||extraLabels.en[c.labelKey]||c.label||c.labelKey,scope:c.scopeLabels?.[lang]||scopes[lang]?.[c.scope]||scopeName(iso||c.scope,lang)};
 }
 primary(scene,lang){
  let cards=this.cards(scene,lang);if(!cards.length)return null;
  const c=cards[0],w=words[lang],d=dictionary(lang);
  return {title:w[scene+'Topic']||copy[lang][scene+'Topic'],short:c.value,value:c.rawValue??0,rawValue:c.rawValue??0,unit:c.label,scope:scopeName('World',lang),year:c.year,source:c.source,url:c.url,estimated:c.estimated,raw:{},label:scene,ratio:2.5,housingPressure:.25,action:sceneWords[lang][scene+'Action'],note:sceneWords[lang][scene+'Note']};
 }
 cards(scene,lang,m){
  if(this.global)return this.global.filter(c=>c.scene===scene).map(c=>({...this.format({...c,rawValue:c.value},lang),scopeCode:c.scope,label:c.labels[lang],format:c.format,definition:c.definition}));
  const out=[],d=dictionary(lang),w=words[lang];
  const add=(value,format,labelKey,scope,year,source,url,extra={})=>out.push(this.format({value,rawValue:value,format,labelKey,scope,year,source,url,...extra},lang));
  if(m&&scene==='hold'&&lang!=='zh'){
   add(m.rawValue,m.label==='careRatio'?'ratio':'hours',m.label==='careRatio'?'careRatio':'womenHours',m.scope,m.year,m.source,m.url);
   if(m.male!=null){add(m.male,'hours','menHours',m.scope,m.year,m.source,m.url);add(m.rawValue-m.male,'hours','gapHours',m.scope,m.year,m.source,m.url,{estimated:true});}
   for(const row of m.raw.countryDetails||[])if(row.femaleHoursDay!=null){add(row.femaleHoursDay,'hours','womenHours',row.iso2,row.surveyYear,m.source,m.url);if(row.maleHoursDay!=null)add(row.maleHoursDay,'hours','menHours',row.iso2,row.surveyYear,m.source,m.url);}
  }
  if(m&&scene==='space'&&lang!=='zh'){
   add(m.rawValue,'percent',m.label==='mortgage'?'mortgage':'housingShare',m.scope,m.year,m.source,m.url,{estimated:m.estimated});
   if(m.raw.reportedPeople||m.raw.estimated&&m.raw.value)add(m.raw.reportedPeople||m.raw.value,'compact','housingPeople',m.scope,m.year,m.source,m.url,{estimated:!m.raw.reportedPeople});
   for(const r of m.raw.countryDetails||[])if(r.value!=null&&/^[A-Z]{2}$/.test(r.iso2))add(r.value,'percent','housingShare',r.iso2,r.year||m.year,m.source,m.url);
  }
  const regional=this.regional[lang]?.[scene];
  if(regional){
   const label=scene==='thirst'?'withoutWater':'offlinePeople',served=scene==='thirst'?'safeWater':'online';
   const scope=regional.countries?.length===1?regional.countries[0].iso2:d.scopes[lang];
   add(regional.peopleWithout,'compact',label,scope,regional.year,scene==='thirst'?'WHO / UNICEF JMP · World Bank':'ITU · World Bank',scene==='thirst'?'https://data.worldbank.org/indicator/SH.H2O.SMDW.ZS':'https://data.worldbank.org/indicator/IT.NET.USER.ZS',{estimated:true,partial:regional.partial,coverage:regional.coverage});
   add(regional.percentCovered,'percent',served,scope,regional.year,out[0].source,out[0].url,{estimated:true});
   for(const c of regional.countries||[])add(c.percent,'percent',served,c.iso2,c.year,out[0].source,out[0].url);
  }
  for(const c of this.extra.filter(c=>!regional&&c.scene===scene&&(c.locale===lang||Array.isArray(c.locales)&&c.locales.includes(lang))))out.push(this.format({...c,rawValue:c.value},lang));
  const seen=new Set();return out.filter(c=>{const key=[c.value,c.label,c.scope,c.year].join('|');if(seen.has(key))return false;seen.add(key);return true;});
 }
}
